/** Build file-search options only while a typeahead query is active. */
export function createFileSearchOptions(repositoryFiles: readonly string[], query: string | null) {
    if (query === null) return []

    return repositoryFiles
        .filter((repositoryPath) => repositoryFileMatchesQuery(repositoryPath, query))
        .map((repositoryPath) => new MarkdownFileSearchOption(repositoryPath))
}
import type { TriggerFn } from '@lexical/react/LexicalTypeaheadMenuPlugin'

const FILE_SEARCH_TRIGGER_PATTERN = /(^|[\s(])@([^\s@]*)$/u

function parseFileSearchTrigger(text: string) {
    const match = FILE_SEARCH_TRIGGER_PATTERN.exec(text)
    if (!match) return null

    const boundary = match[1]
    const query = match[2]

    return {
        leadOffset: match.index + boundary.length,
        matchingString: query,
        replaceableString: `@${query}`,
    }
}

export const matchFileSearchTrigger: TriggerFn = (text) => parseFileSearchTrigger(text)

/** Match file-search trigger only when a repository file index is available. */
export function matchFileSearchTriggerForFiles(text: string, repositoryFiles: readonly string[]) {
    if (repositoryFiles.length === 0) return null

    return parseFileSearchTrigger(text)
}

